draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.rect(W/2 + 50*Math.sin(t), 0, 10, H);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 - 50*Math.sin(t), 0, 10, H);
  ctx.stroke();
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('DIVIDED', W/2 + 60*Math.sin(t), H/2);
  ctx.fillText('UNIFIED', W/2 - 60*Math.sin(t), H/2);
  ctx.restore();
}
